'use strict';

// MODULES //

var EventEmitter = require( 'events' ).EventEmitter;
var tape = require( 'tape' );
var isSameArray = require( '@stdlib/assert/is-same-array' );
var instanceOf = require( '@stdlib/assert/instance-of' );
var Title = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof Title, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function is a constructor', function test( t ) {
	var title = new Title();
	t.strictEqual( instanceOf( title, Title ), true, 'returns expected value' );
	t.end();
});

tape( 'the constructor does not require the `new` keyword', function test( t ) {
	var title;
	var ctor;

	ctor = Title;
	title = ctor();
	t.strictEqual( instanceOf( title, Title ), true, 'returns expected value' );
	t.end();
});

tape( 'the constructor does not require the `new` keyword (options)', function test( t ) {
	var title;
	var ctor;

	ctor = Title;
	title = ctor({
		'text': 'Beep boop'
	});
	t.strictEqual( instanceOf( title, Title ), true, 'returns expected value' );
	t.strictEqual( isSameArray( title.text, [ 'Beep boop' ] ), true, 'returns expected value' );
	t.end();
});

tape( 'the constructor throws an error if provided an options argument which is not an object', function test( t ) {
	var values;
	var i;

	values = [
		'5',
		5,
		NaN,
		null,
		void 0,
		true,
		false,
		[],
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			var title = new Title( value ); // eslint-disable-line no-unused-vars
		};
	}
});

