tape( 'the constructor has a read-only `name` property', function test( t ) {
	t.strictEqual( Title.name, 'Title', 'returns expected value' );
	t.end();
});

tape( 'the constructor returns an instance having a `toJSON` method for serializing an instance to JSON', function test( t ) {
	var expected;
	var title;
	var json;

	title = new Title();
	json = title.toJSON();

	expected = {
		'anchor': 'middle',
		'aria': true,
		'frame': 'bounds',
		'orient': 'top',
		'text': [],
		'zindex': 0
	};
	t.deepEqual( json, expected, 'returns expected value' );
	t.end();
});

tape( 'the constructor returns an instance having a `toJSON` method for serializing an instance to JSON (options)', function test( t ) {
	var expected;
	var title;
	var json;

	title = new Title({
		'text': 'Beep boop',
		'align': 'left',
		'anchor': 'start',
		'angle': 90,
		'aria': false,
		'baseline': 'top',
		'color': 'steelblue',
		'dx': 2,
		'dy': 2,
		'encode': {
			'title': {
				'enter': {
					'fill': {
						'value': 'steelblue'
					}
				}
			}
		},
		'font': 'Arial',
		'fontSize': 12,
		'fontStyle': 'italic',
		'fontWeight': 'bold',
		'frame': 'group',
		'limit': 100,
		'lineHeight': 2,
		'offset': 12,
		'orient': 'bottom',
		'subtitle': 'foo bar',
		'subtitleColor': 'steelblue',
		'subtitleFont': 'Arial',
		'subtitleFontSize': 14,
		'subtitleFontStyle': 'italic',
		'subtitleFontWeight': 'bold',
		'subtitleLineHeight': 16,
		'subtitlePadding': 24,
		'zindex': 2
	});
	json = title.toJSON();

	expected = {
		'align': 'left',
		'anchor': 'start',
		'angle': 90,
		'aria': false,
		'baseline': 'top',
		'color': 'steelblue',
		'dx': 2,
		'dy': 2,
		'encode': {
			'title': {
				'enter': {
					'fill': {
						'value': 'steelblue'
					}
				}
			}
		},
		'font': 'Arial',
		'fontSize': 12,
		'fontStyle': 'italic',
		'fontWeight': 'bold',
		'frame': 'group',
		'limit': 100,
		'lineHeight': 2,
		'offset': 12,
		'orient': 'bottom',
		'subtitle': [ 'foo bar' ],
		'subtitleColor': 'steelblue',
		'subtitleFont': 'Arial',
		'subtitleFontSize': 14,
		'subtitleFontStyle': 'italic',
		'subtitleFontWeight': 'bold',
		'subtitleLineHeight': 16,
		'subtitlePadding': 24,
		'text': [ 'Beep boop' ],
		'zindex': 2
	};
	t.deepEqual( json, expected, 'returns expected value' );
	t.end();
});

tape( 'the `toJSON` method is implicitly invoked by `JSON.stringify`', function test( t ) {
	var expected;
	var title;

	title = new Title({
		'text': 'Beep boop'
	});

	expected = {
		'aria': true,
		'anchor': 'middle',
		'frame': 'bounds',
		'orient': 'top',
		'text': [ 'Beep boop' ],
		'zindex': 0
	};
	t.strictEqual( JSON.stringify( title ), JSON.stringify( expected ), 'returns expected value' );
	t.end();
});

tape( 'the constructor returns an instance which inherits from EventEmitter', function test( t ) {
	var title = new Title();
	t.strictEqual( instanceOf( title, EventEmitter ), true, 'returns expected value' );
	t.end();
});

tape( 'the constructor ignores unrecognized options', function test( t ) {
	var title = new Title({
		'text': 'Beep boop',
		'beep': 'boop',
		'foo': 'bar'
	});

	t.strictEqual( isSameArray( title.text, [ 'Beep boop' ] ), true, 'returns expected value' );
	t.strictEqual( title.beep, void 0, 'returns expected value' );
	t.strictEqual( title.foo, void 0, 'returns expected value' );

	t.end();
});
